import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { createFabricSurface, hexToRgb, loadMaps } from './fabric.js'

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduced(mq.matches)
    on()
    mq.addEventListener('change', on)
    return () => mq.removeEventListener('change', on)
  }, [])
  return reduced
}

export function useFabricMaps() {
  const [maps, setMaps] = useState(null)
  const [failed, setFailed] = useState(false)
  useEffect(() => {
    let live = true
    loadMaps().then(
      (m) => live && setMaps(m),
      () => live && setFailed(true),
    )
    return () => {
      live = false
    }
  }, [])
  return { maps, failed }
}

// A live surface: resizes with its element, redraws when its params change, and
// runs a frame loop only while it is on screen and something is moving.
export function FabricPanel({ maps, dye, scale, stretch = 0, back = 0, light, live = false, grain, className, style }) {
  const canvasRef = useRef(null)
  const surfRef = useRef(null)
  const paramsRef = useRef({})
  const rafRef = useRef(0)
  const visibleRef = useRef(true)

  paramsRef.current = { dye, scale, stretch, back, light, grain }

  useLayoutEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !maps) return
    const surf = createFabricSurface(canvas, maps)
    if (!surf) return
    surfRef.current = surf

    const paint = () => {
      const p = paramsRef.current
      const rect = canvas.getBoundingClientRect()
      if (rect.width && rect.height) surf.resize(rect.width, rect.height)
      surf.draw({
        dye: hexToRgb(p.dye),
        scale: p.scale,
        stretch: p.stretch,
        back: p.back,
        light: p.light || [0.3, 0.7],
        grain: p.grain,
      })
    }
    canvas.__paint = paint

    const ro = new ResizeObserver(paint)
    ro.observe(canvas)
    const io = new IntersectionObserver(([e]) => {
      visibleRef.current = e.isIntersecting
    })
    io.observe(canvas)
    paint()

    return () => {
      ro.disconnect()
      io.disconnect()
      cancelAnimationFrame(rafRef.current)
      surf.destroy()
      surfRef.current = null
    }
  }, [maps])

  // Repaint on any parameter change. Cheap: one triangle.
  useEffect(() => {
    const c = canvasRef.current
    if (c && c.__paint) c.__paint()
  }, [dye, scale, stretch, back, light && light[0], light && light[1], grain, maps])

  // The idle drift, used only where the light is meant to keep moving.
  useEffect(() => {
    if (!live || !maps) return
    const start = performance.now()
    const tick = (t) => {
      rafRef.current = requestAnimationFrame(tick)
      if (!visibleRef.current) return
      const e = (t - start) / 1000
      const c = canvasRef.current
      if (!c || !c.__paint) return
      paramsRef.current = {
        ...paramsRef.current,
        light: [0.32 + Math.sin(e * 0.21) * 0.26, 0.62 + Math.cos(e * 0.17) * 0.2],
      }
      c.__paint()
    }
    rafRef.current = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafRef.current)
  }, [live, maps])

  return <canvas ref={canvasRef} className={className} style={style} aria-hidden="true" />
}

// A tile painted exactly once from a shared offscreen surface. Used for the six
// dye lots and the three magnifications, so the page does not open eleven
// contexts to show eleven states of one cloth.
let sharedCanvas = null
let sharedSurf = null

function getShared(maps, w, h) {
  if (!sharedCanvas) {
    sharedCanvas = document.createElement('canvas')
  }
  if (!sharedSurf) {
    sharedSurf = createFabricSurface(sharedCanvas, maps)
  }
  if (!sharedSurf) return null
  sharedSurf.resize(w, h, 1.4)
  return sharedSurf
}

export function FabricTile({ maps, dye, scale, light = [0.34, 0.7], stretch = 0, className, style, ratio = 1.4 }) {
  const ref = useRef(null)
  useLayoutEffect(() => {
    const el = ref.current
    if (!el || !maps) return
    const rect = el.getBoundingClientRect()
    const w = Math.max(1, Math.round(rect.width || 200))
    const h = Math.max(1, Math.round(rect.height || w / ratio))
    const surf = getShared(maps, w, h)
    if (!surf) return
    surf.draw({ dye: hexToRgb(dye), scale, light, stretch, grain: 0.03 })
    el.width = Math.round(w * 1.4)
    el.height = Math.round(h * 1.4)
    const ctx = el.getContext('2d')
    ctx.drawImage(surf.canvas, 0, 0, el.width, el.height)
  }, [maps, dye, scale, light[0], light[1], stretch])
  return <canvas ref={ref} className={className} style={style} aria-hidden="true" />
}

// Halfmoon — the Contour legging.
//
// The page is built as the garment's own measured document: every claim on it
// is either a number you can check against a centimetre rule, or the real
// cloth, lit, at a magnification where you can see the yarn. The buyer this is
// for has been lied to by a size chart before.
//
// Two things run the whole route. The centimetre rule, which appears in the
// masthead, sizes the chart, sizes the three lengths, and finally carries the
// three reviewers' heights. And the fabric, which is one captured knit surface
// shown in the selected dye at every magnification the page needs.

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { Check, Minus, Ruler, RotateCcw, Truck } from 'lucide-react'
import { FabricPanel, FabricTile, useFabricMaps, usePrefersReducedMotion } from './stage.jsx'

gsap.registerPlugin(ScrollTrigger)

const COLOURWAYS = [
  { id: 'slate', name: 'Slate', price: 88, stock: 'in', hex: '#5F6B77', note: 'The first dye lot, and still the one we make most of.' },
  { id: 'clay', name: 'Burnt Clay', price: 88, stock: 'in', hex: '#A85C39', note: 'A warm red-brown that holds its depth after washing.' },
  { id: 'moss', name: 'Deep Moss', price: 88, stock: 'in', hex: '#53663F', note: 'Dark enough to read as neutral in most light.' },
  { id: 'black', name: 'True Black', price: 84, stock: 'in', hex: '#2A2724', note: 'A single-bath black, which is why it costs four dollars less.' },
  { id: 'oat', name: 'Oat', price: 88, stock: 'out', hex: '#DCCAAB', note: 'The lightest dye we will make in this cloth. Back when the mill runs it again.' },
  { id: 'plum', name: 'Dried Plum', price: 92, stock: 'out', hex: '#75485C', note: 'A slow, expensive dye. Sold out.' },
]

// Waist and hip are the garment laid flat and doubled; inseam is the 26 inch length.
const SIZES = [
  { size: 'XXS', waist: 58, hip: 80, inseam: 66 },
  { size: 'XS', waist: 63, hip: 85, inseam: 66 },
  { size: 'S', waist: 68, hip: 90, inseam: 66 },
  { size: 'M', waist: 74, hip: 96, inseam: 66 },
  { size: 'L', waist: 81, hip: 103, inseam: 67 },
  { size: 'XL', waist: 89, hip: 111, inseam: 67 },
  { size: '2XL', waist: 98, hip: 120, inseam: 68 },
  { size: '3XL', waist: 108, hip: 130, inseam: 68 },
]

const INSEAMS = [
  { id: 'short', label: '24 inch, short', offered: 'XXS to XL', cm: 61, from: 'XXS', to: 'XL' },
  { id: 'regular', label: '26 inch, regular', offered: 'XXS to 3XL', cm: 66, from: 'XXS', to: '3XL' },
  { id: 'tall', label: '28 inch, tall', offered: 'S to 3XL', cm: 71, from: 'S', to: '3XL' },
]

const FABRIC = [
  '78% recycled nylon, 22% elastane, knitted in a single mill in Portugal.',
  '240gsm, heavier than most leggings sold at this price, which is where the opacity comes from.',
  'Opacity tested at full squat under studio light by nine wearers across the size range. No sheerness recorded at any size.',
  'Four-way stretch, so the fabric recovers across the leg as well as along it.',
  'A single diamond gusset, flatlocked, so there is no seam at the crotch to rub or fail.',
]

const REVIEWS = [
  {
    quote:
      'The waistband is the first one I have owned that stays where I put it through a full session. I stopped thinking about it, which is the whole point.',
    name: 'Renata K.',
    fit: '172cm, usually a M, bought M regular',
    height: 172,
  },
  {
    quote:
      'I ordered the tall inseam expecting the usual compromise and it actually reaches my ankle. The fabric is thicker than I expected from the photos.',
    name: 'Junho P.',
    fit: '181cm, usually a L, bought L tall',
    height: 181,
  },
  {
    quote:
      'Sized down after the fit finder told me to and it was right. They are firm at first and settle after an hour.',
    name: 'Amara O.',
    fit: '158cm, usually an S, bought XS short',
    height: 158,
  },
]

const RETURNS =
  'Sixty days to return anything, return shipping is free, and we accept them worn and washed. If they did not work out we would rather have them back than have you keep them in a drawer.'

// The fit finder. Below 165cm recommends the short inseam, above 176cm the tall
// one. It sizes down one step only when the wearer reports being between sizes.
function recommend(height, usualSize, between) {
  const h = Number(height)
  if (!h || !usualSize) return null
  if (h < 140 || h > 210) return { unsure: true }
  const i = SIZES.findIndex((s) => s.size === usualSize)
  if (i < 0) return { unsure: true }
  const size = between && i > 0 ? SIZES[i - 1].size : usualSize
  const inseam = h < 165 ? INSEAMS[0] : h > 176 ? INSEAMS[2] : INSEAMS[1]
  return { size, inseam }
}

const sizeIndex = (s) => SIZES.findIndex((x) => x.size === s)
const offersSize = (ins, size) =>
  !size || (sizeIndex(size) >= sizeIndex(ins.from) && sizeIndex(size) <= sizeIndex(ins.to))

// The rule everything on this page is drawn against. 140cm of it, which is the
// widest hip in the chart plus a margin, so a bar's length is honestly its
// measurement and not a percentage of a box.
const RULE_CM = 140
const pct = (cm) => (cm / RULE_CM) * 100

function Rule({ every = 10, labelled = 20 }) {
  const ticks = []
  for (let cm = 0; cm <= RULE_CM; cm += every) {
    ticks.push(
      <span
        key={cm}
        className={'tick' + (cm % labelled === 0 ? ' tick--major' : '')}
        style={{ left: pct(cm) + '%' }}
      >
        {cm % labelled === 0 ? <i>{cm}</i> : null}
      </span>,
    )
  }
  return (
    <div className="rule" aria-hidden="true">
      {ticks}
    </div>
  )
}

export default function App() {
  const [colourway, setColourway] = useState('')
  const [size, setSize] = useState('')
  const [inseam, setInseam] = useState('')
  const [bag, setBag] = useState(null)
  const [height, setHeight] = useState('')
  const [usualSize, setUsualSize] = useState('')
  const [between, setBetween] = useState(false)

  const chosen = COLOURWAYS.find((c) => c.id === colourway)
  const canAdd = Boolean(chosen && chosen.stock === 'in' && size && inseam)
  const suggestion = recommend(height, usualSize, between)

  function addToBag(e) {
    e.preventDefault()
    if (!canAdd) return
    setBag({
      colourway: chosen.name,
      size,
      inseam: INSEAMS.find((i) => i.id === inseam).label,
      price: chosen.price,
    })
  }

  // --- presentation state -------------------------------------------------
  const { maps, failed } = useFabricMaps()
  const reduced = usePrefersReducedMotion()
  const dye = chosen ? chosen.hex : '#5F6B77'
  const dyeName = chosen ? chosen.name : 'Slate'

  // The opacity test's single authored value. Scroll drives it; the range input
  // drives it too, so the mechanism is reachable by keyboard and by thumb.
  const [test, setTest] = useState(0)
  const testRef = useRef(null)
  const peakRef = useRef(null)
  const draggingRef = useRef(false)

  // A length the label does not offer is not selectable, so the bag can never
  // name a combination that cannot be made.
  useEffect(() => {
    if (inseam && size) {
      const ins = INSEAMS.find((i) => i.id === inseam)
      if (ins && !offersSize(ins, size)) setInseam('')
    }
  }, [size, inseam])

  // Scroll ownership: one trigger, one progress value, reverted on unmount.
  useLayoutEffect(() => {
    if (reduced || !peakRef.current) return
    const ctx = gsap.context(() => {
      ScrollTrigger.create({
        trigger: peakRef.current,
        start: 'top top',
        end: 'bottom bottom',
        scrub: 0.4,
        onUpdate: (self) => {
          if (draggingRef.current) return
          setTest(gsap.utils.clamp(0, 1, (self.progress - 0.06) / 0.78))
        },
      })
    }, peakRef)
    return () => ctx.revert()
  }, [reduced])

  // The regional entrance grammar. One observer, one class, the whole route.
  useEffect(() => {
    const els = document.querySelectorAll('[data-enter]')
    if (reduced) {
      els.forEach((el) => el.setAttribute('data-enter', 'in'))
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          // Measured against the top of the viewport, so a reveal cannot resolve
          // behind a reader who has already gone past it.
          if (e.isIntersecting) {
            e.target.setAttribute('data-enter', 'in')
            io.unobserve(e.target)
          }
        })
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.08 },
    )
    els.forEach((el) => io.observe(el))
    return () => io.disconnect()
  }, [reduced])

  const stretch = test
  const back = gsap.utils.clamp(0, 1, (test - 0.18) / 0.72)
  const testStage =
    test < 0.28
      ? { k: 'Relaxed', t: 'The cloth off the body. 240gsm, which is where all of this starts.' }
      : test < 0.72
        ? { k: 'Mid stretch', t: 'The courses open across the leg. The wales draw in along it.' }
        : { k: 'Full squat', t: 'Lamp behind at full. This is the state nine wearers were photographed in.' }

  const recommendedRow = suggestion && !suggestion.unsure ? suggestion.size : null

  return (
    <div className="page" style={{ '--dye': dye }}>
      <a className="skip" href="#buy">
        Skip to choosing a pair
      </a>

      <Header colourway={chosen} size={size} inseam={inseam} dyeName={dyeName} />

      {/* 1 — masthead ---------------------------------------------------- */}
      <section className="mast" aria-labelledby="mast-h">
        <div className="mast__cloth">
          {maps && !failed ? (
            <FabricPanel maps={maps} dye={dye} scale={3.2} light={[0.3, 0.68]} live={!reduced} className="cv" />
          ) : (
            <div className="cv cv--fallback" style={{ background: dye }} />
          )}
          <figcaption className="mast__cap">
            The cloth, in {dyeName}. Lit live, at about four times life size.
          </figcaption>
        </div>

        <div className="mast__text">
          <p className="brand">Halfmoon</p>
          <h1 id="mast-h">
            The Contour
            <br />
            legging
          </h1>
          <p className="deck">
            One garment. Six dye lots, three lengths, eight sizes, and every measurement on this page
            given in centimetres so you can check it against a pair you already own.
          </p>
          <p className="price">
            <b>$84–92</b> <span>depending on the dye</span>
          </p>
          <nav className="jump" aria-label="On this page">
            <a href="#test">The opacity test</a>
            <a href="#measure">The measure</a>
            <a href="#fit">The fit finder</a>
            <a href="#buy">Choose a pair</a>
          </nav>
        </div>

        <div className="mast__rule">
          <Rule />
          <p className="rule__legend">
            <Ruler size={13} aria-hidden="true" /> centimetres. This rule runs the length of the page.
          </p>
        </div>
      </section>

      {/* 2 — the opacity test (peak) ------------------------------------- */}
      <section className="peak" id="test" ref={peakRef} aria-labelledby="peak-h">
        <div className="peak__sticky">
          <div className="peak__frame">
            <div
              className="peak__lamp"
              style={{ opacity: back, transform: `scale(${1 + back * 0.14})` }}
              aria-hidden="true"
            />
            <div className="peak__cloth">
              {maps && !failed ? (
                <FabricPanel
                  maps={maps}
                  dye={dye}
                  scale={1.15}
                  stretch={stretch}
                  back={back}
                  light={[0.36, 0.66]}
                  className="cv"
                />
              ) : (
                <div className="cv cv--fallback" style={{ background: dye }} />
              )}
            </div>
          </div>

          <div className="peak__panel">
            <p className="eyebrow">The test people ask about first</p>
            <h2 id="peak-h">
              Is it <em>sheer</em>?
            </h2>
            <p className="peak__stage">
              <b>{testStage.k}</b> {testStage.t}
            </p>

            <dl className="readout">
              <div>
                <dt>Stretch</dt>
                <dd>{Math.round(stretch * 100)}%</dd>
              </div>
              <div>
                <dt>Lamp behind</dt>
                <dd>{Math.round(back * 100)}%</dd>
              </div>
              <div>
                <dt>Through the cloth</dt>
                <dd className="readout__result">none recorded</dd>
              </div>
            </dl>

            <label className="scrub">
              <span>Stretch the cloth</span>
              <input
                ref={testRef}
                type="range"
                min="0"
                max="100"
                value={Math.round(test * 100)}
                onChange={(e) => setTest(Number(e.target.value) / 100)}
                onPointerDown={() => (draggingRef.current = true)}
                onPointerUp={() => (draggingRef.current = false)}
                onFocus={() => (draggingRef.current = true)}
                onBlur={() => (draggingRef.current = false)}
                aria-describedby="peak-claim"
              />
            </label>

            <p className="peak__claim" id="peak-claim">
              {FABRIC[2]}
            </p>
          </div>
        </div>
      </section>

      {/* 3 — the dye lots ------------------------------------------------- */}
      <section className="dyes" aria-labelledby="dyes-h" data-enter="out">
        <header className="sec">
          <p className="eyebrow">Step one of three</p>
          <h2 id="dyes-h">Six dye lots</h2>
          <p className="sec__deck">
            The same cloth every time. Two of them are sold out and we have left them here rather than
            hiding them, because the dye is the reason the price moves.
          </p>
        </header>

        <ul className="swatches" role="radiogroup" aria-label="Colourway">
          {COLOURWAYS.map((c) => {
            const out = c.stock === 'out'
            const sel = colourway === c.id
            return (
              <li key={c.id}>
                <button
                  type="button"
                  role="radio"
                  aria-checked={sel}
                  disabled={out}
                  className={'swatch' + (sel ? ' is-selected' : '') + (out ? ' is-out' : '')}
                  onClick={() => setColourway(c.id)}
                >
                  <span className="swatch__cloth">
                    {maps && !failed ? (
                      <FabricTile maps={maps} dye={c.hex} scale={1.9} light={[0.32, 0.72]} />
                    ) : (
                      <span className="cv cv--fallback" style={{ background: c.hex }} />
                    )}
                    {out ? <span className="swatch__veil" /> : null}
                  </span>
                  <span className="swatch__meta">
                    <b>{c.name}</b>
                    <span className="swatch__price">${c.price}</span>
                    <span className={'swatch__stock' + (out ? ' is-out' : '')}>
                      {out ? (
                        <>
                          <Minus size={12} aria-hidden="true" /> sold out
                        </>
                      ) : sel ? (
                        <>
                          <Check size={12} aria-hidden="true" /> chosen
                        </>
                      ) : (
                        'in stock'
                      )}
                    </span>
                  </span>
                </button>
              </li>
            )
          })}
        </ul>

        <p className="swatches__note" aria-live="polite">
          {chosen ? (
            <>
              <b>{chosen.name}, ${chosen.price}.</b> {chosen.note}
            </>
          ) : (
            <>Pick a dye. It sets the colour of the cloth everywhere else on this page.</>
          )}
        </p>
      </section>

      {/* 4 — the measure -------------------------------------------------- */}
      <section className="measure" id="measure" aria-labelledby="measure-h" data-enter="out">
        <header className="sec">
          <p className="eyebrow">Step two of three</p>
          <h2 id="measure-h">The measure</h2>
          <p className="sec__deck">
            Every bar below is drawn at its real length against the same centimetre rule. Waist and hip
            are the garment laid flat and doubled; the inseam column is the 26 inch length. Lay a pair
            you already own on the floor and compare.
          </p>
        </header>

        <div className="measure__body">
          <FitFinder
            height={height}
            setHeight={setHeight}
            usualSize={usualSize}
            setUsualSize={setUsualSize}
            between={between}
            setBetween={setBetween}
            suggestion={suggestion}
            onUse={() => {
              if (suggestion && !suggestion.unsure) {
                setSize(suggestion.size)
                setInseam(suggestion.inseam.id)
              }
            }}
          />

          <div className="chart" role="radiogroup" aria-label="Size">
            <div className="chart__scale">
              <Rule />
            </div>
            <ol className="chart__rows">
              {SIZES.map((s) => {
                const sel = size === s.size
                const rec = recommendedRow === s.size
                return (
                  <li key={s.size}>
                    <button
                      type="button"
                      role="radio"
                      aria-checked={sel}
                      className={'row' + (sel ? ' is-selected' : '') + (rec ? ' is-rec' : '')}
                      onClick={() => setSize(s.size)}
                      aria-label={`Size ${s.size}, waist ${s.waist} centimetres, hip ${s.hip} centimetres, inseam ${s.inseam} centimetres`}
                    >
                      <span className="row__size">{s.size}</span>
                      <span className="row__bars">
                        <span className="bar bar--waist" style={{ width: pct(s.waist) + '%' }}>
                          <i>
                            waist <b>{s.waist}</b>
                          </i>
                        </span>
                        <span className="bar bar--hip" style={{ width: pct(s.hip) + '%' }}>
                          <i>
                            hip <b>{s.hip}</b>
                          </i>
                        </span>
                      </span>
                      <span className="row__inseam">
                        inseam <b>{s.inseam}</b>cm
                      </span>
                      {rec ? <span className="row__flag">the fit finder sent you here</span> : null}
                    </button>
                  </li>
                )
              })}
            </ol>
          </div>
        </div>
      </section>

      {/* 5 — the three lengths -------------------------------------------- */}
      <section className="lengths" aria-labelledby="len-h" data-enter="out">
        <header className="sec">
          <p className="eyebrow">Step three of three</p>
          <h2 id="len-h">Three lengths</h2>
          <p className="sec__deck">
            Drawn against the same rule, turned on its side. Not every length is cut in every size,
            and we would rather say so here than at checkout.
          </p>
        </header>

        <ul className="len" role="radiogroup" aria-label="Inseam">
          {INSEAMS.map((i) => {
            const ok = offersSize(i, size)
            const sel = inseam === i.id
            return (
              <li key={i.id}>
                <button
                  type="button"
                  role="radio"
                  aria-checked={sel}
                  disabled={!ok}
                  className={'len__opt' + (sel ? ' is-selected' : '') + (!ok ? ' is-off' : '')}
                  onClick={() => setInseam(i.id)}
                >
                  <span className="len__draw" aria-hidden="true">
                    <span className="len__line" style={{ height: (i.cm / 75) * 100 + '%' }}>
                      <i />
                    </span>
                  </span>
                  <span className="len__meta">
                    <b>{i.label}</b>
                    <span className="len__cm">{i.cm}cm on a size M</span>
                    <span className="len__offered">
                      offered {i.offered}
                      {!ok ? <em> — not cut in {size}</em> : null}
                    </span>
                  </span>
                </button>
              </li>
            )
          })}
        </ul>
      </section>

      {/* 6 — the build ---------------------------------------------------- */}
      <section className="build" aria-labelledby="build-h" data-enter="out">
        <header className="sec">
          <p className="eyebrow">What it is made of</p>
          <h2 id="build-h">The cloth, closer</h2>
          <p className="sec__deck">
            The same surface as the test above, at three magnifications. Nothing here is a stock photo
            of somebody else's legging.
          </p>
        </header>

        <div className="build__grid">
          <figure className="mag mag--near">
            <span className="mag__cloth">
              {maps && !failed ? (
                <FabricTile maps={maps} dye={dye} scale={0.65} light={[0.28, 0.74]} />
              ) : (
                <span className="cv cv--fallback" style={{ background: dye }} />
              )}
              <span className="mag__label">≈ 12×</span>
            </span>
            <figcaption>
              <h3>The yarn</h3>
              <p>{FABRIC[0]}</p>
              <p className="mag__second">{FABRIC[3]}</p>
            </figcaption>
          </figure>

          <figure className="mag mag--mid">
            <span className="mag__cloth">
              {maps && !failed ? (
                <FabricTile maps={maps} dye={dye} scale={2.6} light={[0.4, 0.6]} />
              ) : (
                <span className="cv cv--fallback" style={{ background: dye }} />
              )}
              <span className="mag__label">≈ 4×</span>
            </span>
            <figcaption>
              <h3>The weight</h3>
              <p>{FABRIC[1]}</p>
            </figcaption>
          </figure>

          <figure className="mag mag--gusset">
            <span className="mag__cloth">
              {maps && !failed ? (
                <FabricTile maps={maps} dye={dye} scale={1.4} light={[0.5, 0.55]} />
              ) : (
                <span className="cv cv--fallback" style={{ background: dye }} />
              )}
              <GussetDiagram />
            </span>
            <figcaption>
              <h3>The gusset</h3>
              <p>{FABRIC[4]}</p>
              <p className="mag__second mag__note">
                Drawn over the real cloth — a construction diagram, not a photograph of the seam.
              </p>
            </figcaption>
          </figure>
        </div>
      </section>

      {/* 7 — worn by ------------------------------------------------------ */}
      <section className="worn" aria-labelledby="worn-h" data-enter="out">
        <header className="sec">
          <p className="eyebrow">Three people, on the same rule</p>
          <h2 id="worn-h">Worn by</h2>
          <p className="sec__deck">
            Each review is placed at the height its writer gave us, so you can find the one nearest
            your own before you read it.
          </p>
        </header>

        <div className="worn__body">
          <div className="worn__rule" aria-hidden="true">
            {[150, 160, 170, 180, 190].map((cm) => (
              <span key={cm} className="worn__tick" style={{ bottom: ((cm - 145) / 50) * 100 + '%' }}>
                <i>{cm}</i>
              </span>
            ))}
          </div>
          <ol className="worn__list">
            {[...REVIEWS]
              .sort((a, b) => b.height - a.height)
              .map((r) => (
                <li key={r.name} className="review" style={{ '--h': ((r.height - 145) / 50) * 100 }}>
                  <p className="review__fit">
                    <span className="review__h">{r.height}cm</span>
                    {r.fit}
                  </p>
                  <blockquote>{r.quote}</blockquote>
                  <p className="review__name">{r.name}</p>
                </li>
              ))}
          </ol>
        </div>
      </section>

      {/* 8 — decide ------------------------------------------------------- */}
      <section className="buy" id="buy" aria-labelledby="buy-h" data-enter="out">
        <div className="buy__cloth" aria-hidden="true">
          {maps && !failed ? (
            <FabricPanel maps={maps} dye={dye} scale={5.5} light={[0.5, 0.5]} grain={0.02} className="cv" />
          ) : (
            <div className="cv cv--fallback" style={{ background: dye }} />
          )}
        </div>

        <div className="buy__inner">
          <header className="sec sec--onCloth">
            <p className="eyebrow">Everything you chose</p>
            <h2 id="buy-h">Your Contour</h2>
          </header>

          <form onSubmit={addToBag} className="buy__form">
            <ol className="picked">
              <li className={colourway ? 'is-done' : ''}>
                <span className="picked__k">Dye</span>
                <span className="picked__v">{chosen ? `${chosen.name}, $${chosen.price}` : 'not chosen'}</span>
                {!colourway ? <a href="#dyes-h">choose</a> : null}
              </li>
              <li className={size ? 'is-done' : ''}>
                <span className="picked__k">Size</span>
                <span className="picked__v">
                  {size
                    ? `${size} — waist ${SIZES[sizeIndex(size)].waist}cm, hip ${SIZES[sizeIndex(size)].hip}cm`
                    : 'not chosen'}
                </span>
                {!size ? <a href="#measure">choose</a> : null}
              </li>
              <li className={inseam ? 'is-done' : ''}>
                <span className="picked__k">Length</span>
                <span className="picked__v">
                  {inseam ? INSEAMS.find((i) => i.id === inseam).label : 'not chosen'}
                </span>
                {!inseam ? <a href="#len-h">choose</a> : null}
              </li>
            </ol>

            <button type="submit" className="add" disabled={!canAdd}>
              {canAdd ? `Add to bag — $${chosen.price}` : 'Add to bag'}
            </button>
            {!canAdd && chosen && chosen.stock === 'out' ? (
              <p className="add__why">{chosen.name} is sold out. Pick another dye.</p>
            ) : !canAdd ? (
              <p className="add__why">Choose a dye, a size and a length first.</p>
            ) : null}
          </form>

          <p className="bag" aria-live="polite">
            {bag ? (
              <>
                In your bag: the Contour legging in {bag.colourway}, size {bag.size}, {bag.inseam},{' '}
                {bag.price} dollars.
              </>
            ) : null}
          </p>
        </div>
      </section>

      {/* returns ----------------------------------------------------------- */}
      <section className="returns" aria-labelledby="ret-h" data-enter="out">
        <h2 id="ret-h" className="sr-only">
          Returns
        </h2>
        <p className="returns__body">{RETURNS}</p>
        <ul className="returns__facts">
          <li>
            <RotateCcw size={16} aria-hidden="true" />
            <b>60 days</b> to send them back
          </li>
          <li>
            <Truck size={16} aria-hidden="true" />
            <b>Free</b> return shipping
          </li>
          <li>
            <Check size={16} aria-hidden="true" />
            <b>Worn and washed</b> returns accepted
          </li>
        </ul>
      </section>

      <footer className="foot">
        <p className="foot__mark">Halfmoon</p>
        <p>
          The cloth on this page is a photographic capture of a technical sportswear jersey, released
          CC0 by{' '}
          <a href="https://ambientcg.com/view?id=Fabric075" rel="noreferrer">
            ambientCG (Fabric075)
          </a>
          , relit and dyed live in the browser. Type is Cabinet Grotesk, Switzer and Erode.
        </p>
      </footer>
    </div>
  )
}

function Header({ colourway, size, inseam, dyeName }) {
  const parts = [
    colourway ? colourway.name : null,
    size || null,
    inseam ? INSEAMS.find((i) => i.id === inseam).label.split(',')[0] : null,
  ]
  const done = parts.filter(Boolean).length
  return (
    <header className="bar">
      <a className="bar__mark" href="#top">
        Halfmoon
      </a>
      <p className="bar__product">The Contour legging</p>
      <div className="bar__state">
        <span className="bar__dots" aria-hidden="true">
          {[0, 1, 2].map((i) => (
            <i key={i} className={i < done ? 'on' : ''} />
          ))}
        </span>
        <span className="bar__parts">
          {done ? parts.filter(Boolean).join(' · ') : `${dyeName} — nothing chosen yet`}
        </span>
        <a className="bar__cta" href="#buy">
          {colourway ? `$${colourway.price}` : 'Choose'}
        </a>
      </div>
    </header>
  )
}

function FitFinder({ height, setHeight, usualSize, setUsualSize, between, setBetween, suggestion, onUse }) {
  return (
    <div className="fit" id="fit">
      <h3>The fit finder</h3>
      <p className="fit__intro">
        Two answers. It sizes down only if you tell us you are between sizes, and it says so when it
        does not know.
      </p>

      <div className="fit__fields">
        <label className="field">
          <span>Your height in cm</span>
          <input
            value={height}
            onChange={(e) => setHeight(e.target.value)}
            inputMode="numeric"
            placeholder="e.g. 168"
          />
        </label>
        <label className="field">
          <span>The size you usually wear</span>
          <select value={usualSize} onChange={(e) => setUsualSize(e.target.value)}>
            <option value="">choose</option>
            {SIZES.map((s) => (
              <option key={s.size} value={s.size}>
                {s.size}
              </option>
            ))}
          </select>
        </label>
      </div>

      <label className="check">
        <input type="checkbox" checked={between} onChange={(e) => setBetween(e.target.checked)} />
        <span>I am usually between sizes</span>
      </label>

      <div className="fit__out" aria-live="polite">
        {suggestion && suggestion.unsure && (
          <p className="fit__unsure">
            We are not confident enough to recommend a size from that. The chart is above.
          </p>
        )}
        {suggestion && !suggestion.unsure && (
          <>
            <p className="fit__say">
              We would send you the <b>{suggestion.size}</b> in the <b>{suggestion.inseam.label}</b>.
            </p>
            <button type="button" className="fit__use" onClick={onUse}>
              Use this
            </button>
          </>
        )}
        {!suggestion && <p className="fit__idle">Answer both and we will point at a row.</p>}
      </div>
    </div>
  )
}

// Notation, drawn over the real cloth: the diamond gusset and its flatlock, in
// the language of a pattern sheet rather than a rendering of one.
function GussetDiagram() {
  return (
    <svg className="gusset" viewBox="0 0 200 200" aria-hidden="true">
      <g fill="none" stroke="currentColor" strokeWidth="1.1" vectorEffect="non-scaling-stroke">
        <path d="M100 62 L138 100 L100 138 L62 100 Z" />
        <path d="M100 62 L138 100 L100 138 L62 100 Z" strokeDasharray="3 4" transform="scale(1.13) translate(-11.5 -11.5)" />
        <path d="M62 100 L20 148 M138 100 L180 148" />
        <path d="M100 62 L100 24" strokeDasharray="2 5" />
      </g>
      <g className="gusset__note" fill="currentColor">
        <text x="100" y="104" textAnchor="middle">diamond</text>
        <text x="100" y="118" textAnchor="middle">one piece</text>
        <text x="150" y="46">flatlock, no crotch seam</text>
      </g>
      <path d="M146 50 L120 74" stroke="currentColor" strokeWidth="1" fill="none" vectorEffect="non-scaling-stroke" />
    </svg>
  )
}

/* Halfmoon — the Contour legging.
   Paper is the Oat dye lot; ink is the darkest one. The accent is whichever
   colourway the reader has chosen, so the page is dyed by the decision. */

@font-face { font-family: 'Cabinet'; src: url('/fonts/cabinet-grotesk-500.woff2') format('woff2'); font-weight: 500; font-display: swap; }
@font-face { font-family: 'Cabinet'; src: url('/fonts/cabinet-grotesk-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }
@font-face { font-family: 'Cabinet'; src: url('/fonts/cabinet-grotesk-800.woff2') format('woff2'); font-weight: 800; font-display: swap; }
@font-face { font-family: 'Switzer'; src: url('/fonts/switzer-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Switzer'; src: url('/fonts/switzer-500.woff2') format('woff2'); font-weight: 500; font-display: swap; }
@font-face { font-family: 'Switzer'; src: url('/fonts/switzer-600.woff2') format('woff2'); font-weight: 600; font-display: swap; }
@font-face { font-family: 'Switzer'; src: url('/fonts/switzer-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }
@font-face { font-family: 'Erode'; src: url('/fonts/erode-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Erode'; src: url('/fonts/erode-500.woff2') format('woff2'); font-weight: 500; font-display: swap; }

:root {
  --paper: #f0eae0;
  --paper-2: #e7dfd1;
  --paper-3: #ded4c2;
  --ink: #1a1815;
  --ink-2: #5c5548;
  --ink-3: #8a8172;
  --rule: #c9bfac;
  --dye: #5f6b77;

  --sans: 'Switzer', ui-sans-serif, system-ui, sans-serif;
  --disp: 'Cabinet', 'Switzer', system-ui, sans-serif;
  --voice: 'Erode', Georgia, serif;

  --gut: clamp(20px, 4.4vw, 72px);
  --ease: cubic-bezier(0.22, 0.7, 0.24, 1);
  --t: 150ms;

  --num: 'tnum' 1, 'lnum' 1;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3 { font-family: var(--disp); font-weight: 700; letter-spacing: -0.022em; margin: 0; line-height: 0.98; }
p { margin: 0; }
b, strong { font-weight: 600; }
a { color: inherit; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip {
  position: fixed; left: 12px; top: -60px; z-index: 90;
  background: var(--ink); color: var(--paper); padding: 10px 16px;
  text-decoration: none; font-size: 14px; transition: top var(--t) var(--ease);
}
.skip:focus { top: 12px; }

:focus-visible {
  outline: 2px solid var(--dye);
  outline-offset: 3px;
}

.cv { display: block; width: 100%; height: 100%; }
.cv--fallback { display: block; width: 100%; height: 100%; }

/* --- the interaction baseline ------------------------------------------ */
button, a, input, select, label { transition: color var(--t) var(--ease), background-color var(--t) var(--ease), border-color var(--t) var(--ease), transform var(--t) var(--ease), opacity var(--t) var(--ease); }
button { font: inherit; cursor: pointer; }
button:disabled { cursor: not-allowed; }

/* --- regional entrance --------------------------------------------------- */
[data-enter='out'] { opacity: 0; transform: translateY(14px); }
[data-enter] { transition: opacity 520ms var(--ease), transform 520ms var(--ease); }
[data-enter='in'] { opacity: 1; transform: none; }

/* --- the rule ------------------------------------------------------------ */
.rule {
  position: relative; height: 26px;
  border-top: 1px solid var(--rule);
}
.rule .tick { position: absolute; top: 0; width: 1px; height: 5px; background: var(--rule); }
.rule .tick--major { height: 10px; background: var(--ink-3); }
.rule .tick i {
  position: absolute; top: 12px; left: 0; transform: translateX(-50%);
  font-size: 10px; font-style: normal; letter-spacing: 0.06em; color: var(--ink-3);
  font-variant-numeric: var(--num);
}

/* --- sticky bar ---------------------------------------------------------- */
.bar {
  position: sticky; top: 0; z-index: 60;
  display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 18px;
  padding: 10px var(--gut);
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--rule);
  font-size: 13px;
}
.bar__mark {
  font-family: var(--disp); font-weight: 800; font-size: 17px;
  letter-spacing: -0.02em; text-decoration: none;
}
.bar__product { color: var(--ink-2); }
.bar__state { display: flex; align-items: center; gap: 12px; }
.bar__dots { display: inline-flex; gap: 4px; }
.bar__dots i { width: 6px; height: 6px; border: 1px solid var(--ink-3); border-radius: 50%; }
.bar__dots i.on { background: var(--dye); border-color: var(--dye); }
.bar__parts { color: var(--ink-2); font-variant-numeric: var(--num); }
.bar__cta {
  text-decoration: none; padding: 5px 13px; border: 1px solid var(--ink);
  font-weight: 600; font-variant-numeric: var(--num);
}
.bar__cta:hover { background: var(--ink); color: var(--paper); }

/* --- 1 masthead ---------------------------------------------------------- */
.mast {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 1fr);
  grid-template-areas: 'text cloth' 'rule rule';
  gap: 0 clamp(28px, 4vw, 64px);
  padding: clamp(40px, 6vw, 84px) var(--gut) 0;
  align-items: end;
  min-height: 88vh;
}
.mast__text { grid-area: text; padding-bottom: clamp(18px, 3vw, 42px); }
.brand {
  font-family: var(--disp); font-weight: 800; font-size: 13px;
  letter-spacing: 0.2em; text-transform: uppercase; color: var(--dye);
  margin-bottom: 22px;
}
.mast h1 {
  font-size: clamp(46px, 8.4vw, 116px);
  font-weight: 800;
  letter-spacing: -0.04em;
  margin-bottom: 26px;
}
.deck {
  max-width: 44ch; font-size: clamp(15px, 1.15vw, 18px);
  color: var(--ink-2); margin-bottom: 26px;
}
.price { font-variant-numeric: var(--num); margin-bottom: 28px; }
.price b { font-family: var(--disp); font-size: 26px; font-weight: 700; }
.price span { color: var(--ink-3); font-size: 13px; margin-left: 8px; }
.jump { display: flex; flex-wrap: wrap; gap: 8px 10px; }
.jump a {
  font-size: 13px; text-decoration: none; padding: 6px 12px;
  border: 1px solid var(--rule); color: var(--ink-2);
}
.jump a:hover { border-color: var(--ink); color: var(--ink); transform: translateY(-1px); }

.mast__cloth { grid-area: cloth; position: relative; }
.mast__cloth .cv, .mast__cloth .cv--fallback {
  height: clamp(320px, 52vh, 560px);
  box-shadow: 0 22px 50px -30px rgba(26, 24, 21, 0.55);
}
.mast__cap {
  position: absolute; left: 0; bottom: -30px;
  font-size: 11.5px; color: var(--ink-3); letter-spacing: 0.01em;
}
.mast__rule { grid-area: rule; margin-top: clamp(52px, 6vw, 86px); }
.rule__legend {
  display: flex; align-items: center; gap: 7px;
  margin-top: 14px; font-size: 12px; color: var(--ink-3);
}

/* --- 2 the opacity test -------------------------------------------------- */
.peak { position: relative; height: 320vh; margin-top: clamp(48px, 7vw, 96px); }
.peak__sticky {
  position: sticky; top: 0; height: 100vh;
  display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.72fr);
  align-items: center; gap: clamp(24px, 3vw, 56px);
  padding: 64px var(--gut) 48px;
  background: var(--paper);
}
.peak__frame { position: relative; height: min(74vh, 620px); }
.peak__lamp {
  position: absolute; inset: -14% -9%;
  background: radial-gradient(ellipse at 50% 50%, rgba(255, 246, 225, 0.95), rgba(255, 240, 205, 0.5) 42%, rgba(255, 236, 195, 0) 72%);
  filter: blur(14px);
  transition: opacity 90ms linear;
  pointer-events: none;
}
.peak__cloth { position: absolute; inset: 0; overflow: hidden; }
.peak__cloth .cv, .peak__cloth .cv--fallback { height: 100%; }

.peak__panel { position: relative; }
.eyebrow {
  font-family: var(--disp); font-weight: 700; font-size: 11.5px;
  letter-spacing: 0.19em; text-transform: uppercase; color: var(--dye);
  margin-bottom: 14px;
}
.peak h2 { font-size: clamp(38px, 4.6vw, 66px); font-weight: 800; letter-spacing: -0.035em; margin-bottom: 20px; }
.peak h2 em { font-style: normal; color: var(--dye); }
.peak__stage {
  font-size: 15px; color: var(--ink-2); min-height: 3.2em;
  max-width: 34ch; margin-bottom: 22px;
}
.peak__stage b { display: block; font-family: var(--disp); color: var(--ink); font-size: 17px; }

.readout {
  display: grid; gap: 0; margin: 0 0 24px;
  border-top: 1px solid var(--rule);
}
.readout > div {
  display: grid; grid-template-columns: 1fr auto; align-items: baseline;
  padding: 9px 0; border-bottom: 1px solid var(--rule);
}
.readout dt { font-size: 12.5px; color: var(--ink-3); letter-spacing: 0.04em; }
.readout dd {
  margin: 0; font-family: var(--disp); font-weight: 700; font-size: 20px;
  font-variant-numeric: var(--num);
}
.readout__result { color: var(--dye); font-size: 15px !important; }

.scrub { display: block; margin-bottom: 20px; }
.scrub span { display: block; font-size: 12px; color: var(--ink-3); margin-bottom: 8px; letter-spacing: 0.05em; }
.scrub input[type='range'] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 22px; background: transparent; cursor: ew-resize;
}
.scrub input[type='range']::-webkit-slider-runnable-track {
  height: 2px; background: var(--rule);
}
.scrub input[type='range']::-moz-range-track { height: 2px; background: var(--rule); }
.scrub input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 16px; height: 16px; margin-top: -7px; border-radius: 50%;
  background: var(--dye); border: 2px solid var(--paper);
  box-shadow: 0 0 0 1px var(--ink);
}
.scrub input[type='range']::-moz-range-thumb {
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--dye); border: 2px solid var(--paper); box-shadow: 0 0 0 1px var(--ink);
}
.peak__claim {
  font-size: 13px; color: var(--ink-2); max-width: 38ch;
  padding-left: 14px; border-left: 2px solid var(--dye);
}

/* --- section headers ----------------------------------------------------- */
.sec { max-width: 62ch; margin-bottom: clamp(30px, 3.6vw, 52px); }
.sec h2 {
  font-size: clamp(32px, 4.1vw, 58px); font-weight: 800;
  letter-spacing: -0.035em; margin-bottom: 16px;
}
.sec__deck { color: var(--ink-2); font-size: clamp(14.5px, 1.05vw, 17px); max-width: 54ch; }

section { padding: clamp(64px, 8vw, 132px) var(--gut); }

/* --- 3 the dye lots ------------------------------------------------------ */
.dyes { border-top: 1px solid var(--rule); }
.swatches {
  list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 3px;
}
.swatch {
  display: block; width: 100%; padding: 0; text-align: left;
  background: none; border: 0; position: relative;
}
.swatch__cloth {
  display: block; position: relative; aspect-ratio: 3 / 4.4; overflow: hidden;
  background: var(--paper-3);
}
.swatch__cloth canvas, .swatch__cloth .cv--fallback { display: block; width: 100%; height: 100%; }
.swatch__veil {
  position: absolute; inset: 0;
  background: color-mix(in srgb, var(--paper) 62%, transparent);
  background-image: repeating-linear-gradient(-45deg, transparent 0 9px, color-mix(in srgb, var(--ink) 14%, transparent) 9px 10px);
}
.swatch__meta { display: block; padding: 12px 2px 0; }
.swatch__meta b { display: block; font-family: var(--disp); font-size: 16px; letter-spacing: -0.01em; }
.swatch__price { display: block; font-size: 13px; color: var(--ink-2); font-variant-numeric: var(--num); }
.swatch__stock {
  display: inline-flex; align-items: center; gap: 4px;
  margin-top: 5px; font-size: 11px; letter-spacing: 0.07em;
  text-transform: uppercase; color: var(--ink-3);
}
.swatch__stock.is-out { color: #9b4a35; }
.swatch:not(:disabled):hover .swatch__cloth { transform: translateY(-4px); }
.swatch__cloth { transition: transform var(--t) var(--ease), box-shadow var(--t) var(--ease); }
.swatch:not(:disabled):hover .swatch__cloth { box-shadow: 0 14px 26px -18px rgba(26, 24, 21, 0.7); }
.swatch.is-selected .swatch__cloth { outline: 2px solid var(--ink); outline-offset: 3px; }
.swatch.is-selected .swatch__stock { color: var(--dye); font-weight: 600; }
.swatch.is-out { opacity: 0.82; }
.swatches__note {
  margin-top: 26px; padding-top: 16px; border-top: 1px solid var(--rule);
  font-size: 15px; color: var(--ink-2); max-width: 60ch; min-height: 3em;
}
.swatches__note b { color: var(--ink); font-variant-numeric: var(--num); }

/* --- 4 the measure ------------------------------------------------------- */
.measure { background: var(--paper-2); }
.measure__body {
  display: grid; grid-template-columns: minmax(260px, 0.62fr) minmax(0, 1.6fr);
  gap: clamp(26px, 3.4vw, 62px); align-items: start;
}

.fit {
  position: sticky; top: 62px;
  background: var(--paper); border: 1px solid var(--rule);
  padding: 22px 22px 20px;
}
.fit h3 { font-size: 21px; margin-bottom: 8px; }
.fit__intro { font-size: 13px; color: var(--ink-2); margin-bottom: 18px; }
.fit__fields { display: grid; gap: 12px; margin-bottom: 12px; }
.field span { display: block; font-size: 11.5px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-3); margin-bottom: 5px; }
.field input, .field select {
  width: 100%; font: inherit; font-size: 15px; padding: 9px 11px;
  background: var(--paper); color: var(--ink);
  border: 1px solid var(--ink-3); border-radius: 0;
  font-variant-numeric: var(--num);
}
.field input:hover, .field select:hover { border-color: var(--ink); }
.check { display: flex; align-items: center; gap: 9px; font-size: 13.5px; cursor: pointer; margin-bottom: 18px; }
.check input { width: 16px; height: 16px; accent-color: var(--dye); }
.fit__out { border-top: 1px solid var(--rule); padding-top: 14px; }
.fit__idle { font-size: 13px; color: var(--ink-3); }
.fit__unsure { font-size: 14px; color: var(--ink-2); border-left: 2px solid #9b4a35; padding-left: 12px; }
.fit__say { font-size: 16px; margin-bottom: 12px; }
.fit__say b { font-family: var(--disp); font-weight: 700; color: var(--dye); }
.fit__use {
  background: var(--ink); color: var(--paper); border: 0;
  padding: 8px 16px; font-size: 13px; font-weight: 600;
}
.fit__use:hover { background: var(--dye); }
.fit__use:active { transform: translateY(1px); }

.chart__scale { padding-left: 62px; padding-right: 108px; margin-bottom: 4px; }
.chart__rows { list-style: none; margin: 0; padding: 0; }
.row {
  display: grid; grid-template-columns: 62px minmax(0, 1fr) 108px;
  align-items: center; gap: 0;
  width: 100%; padding: 9px 0; text-align: left;
  background: none; border: 0; border-bottom: 1px solid var(--rule);
  position: relative;
}
.row:hover { background: color-mix(in srgb, var(--paper) 70%, transparent); }
.row:hover .bar { filter: brightness(1.06); }
.row__size {
  font-family: var(--disp); font-weight: 700; font-size: 19px;
  font-variant-numeric: var(--num);
}
.row__bars { display: grid; gap: 3px; }
.bar {
  display: flex; align-items: center; height: 15px;
  transition: width 320ms var(--ease), filter var(--t) var(--ease);
  position: relative;
}
.bar--waist { background: var(--dye); }
.bar--hip { background: color-mix(in srgb, var(--dye) 42%, var(--paper-3)); }
.bar i {
  position: absolute; left: calc(100% + 8px); white-space: nowrap;
  font-style: normal; font-size: 11px; color: var(--ink-3);
  letter-spacing: 0.04em; font-variant-numeric: var(--num);
}
.bar i b { color: var(--ink); font-weight: 600; font-size: 12.5px; }
.row__inseam {
  text-align: right; font-size: 12px; color: var(--ink-3);
  font-variant-numeric: var(--num);
}
.row__inseam b { color: var(--ink-2); font-size: 14px; }
.row.is-selected { background: var(--paper); box-shadow: inset 3px 0 0 var(--ink); }
.row.is-selected .row__size { color: var(--dye); }
.row.is-rec::after {
  content: ''; position: absolute; left: -14px; top: 50%;
  width: 8px; height: 8px; margin-top: -4px; background: var(--dye);
  border-radius: 50%;
}
.row__flag {
  position: absolute; right: 0; top: -8px;
  font-size: 10px; letter-spacing: 0.07em; text-transform: uppercase;
  color: var(--dye);
}

/* --- 5 the three lengths ------------------------------------------------- */
.len { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(14px, 2vw, 34px); max-width: 900px; }
.len__opt {
  display: grid; grid-template-rows: 1fr auto; gap: 18px;
  width: 100%; padding: 18px 16px; text-align: left;
  background: none; border: 1px solid var(--rule);
}
.len__opt:not(:disabled):hover { border-color: var(--ink); transform: translateY(-2px); }
.len__opt.is-selected { border-color: var(--ink); background: var(--paper-2); box-shadow: inset 0 -3px 0 var(--dye); }
.len__opt.is-off { opacity: 0.45; }
.len__draw { display: flex; align-items: flex-end; justify-content: center; height: 180px; }
.len__line { display: block; width: 3px; background: var(--dye); position: relative; }
.len__line i {
  position: absolute; left: -7px; top: 0; width: 17px; height: 1px; background: var(--ink);
}
.len__line::after { content: ''; position: absolute; left: -7px; bottom: 0; width: 17px; height: 1px; background: var(--ink); }
.len__meta b { display: block; font-family: var(--disp); font-size: 17px; margin-bottom: 4px; }
.len__cm { display: block; font-size: 12.5px; color: var(--ink-2); font-variant-numeric: var(--num); }
.len__offered { display: block; margin-top: 6px; font-size: 11.5px; letter-spacing: 0.05em; text-transform: uppercase; color: var(--ink-3); }
.len__offered em { color: #9b4a35; font-style: normal; }

/* --- 6 the build --------------------------------------------------------- */
.build { background: var(--ink); color: var(--paper); }
.build .sec h2 { color: var(--paper); }
.build .sec__deck { color: #b6ad9d; }
.build .eyebrow { color: color-mix(in srgb, var(--dye) 70%, #ffffff); }
.build__grid {
  display: grid; grid-template-columns: repeat(12, 1fr);
  gap: clamp(20px, 2.6vw, 44px) clamp(18px, 2.2vw, 38px);
}
.mag { margin: 0; }
.mag--near { grid-column: span 7; }
.mag--mid { grid-column: span 5; }
.mag--gusset { grid-column: span 12; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: clamp(20px, 3vw, 52px); align-items: center; }
.mag__cloth { display: block; position: relative; overflow: hidden; background: #221f1c; }
.mag--near .mag__cloth { aspect-ratio: 16 / 10; }
.mag--mid .mag__cloth { aspect-ratio: 16 / 13; }
.mag--gusset .mag__cloth { aspect-ratio: 16 / 9; color: rgba(255, 250, 240, 0.86); }
.mag__cloth canvas, .mag__cloth .cv--fallback { display: block; width: 100%; height: 100%; }
.mag__label {
  position: absolute; left: 12px; top: 10px;
  font-size: 11px; letter-spacing: 0.12em; color: rgba(255, 250, 240, 0.8);
  background: rgba(20, 18, 16, 0.42); padding: 3px 8px; backdrop-filter: blur(3px);
  font-variant-numeric: var(--num);
}
.mag figcaption { padding-top: 16px; }
.mag h3 { font-size: clamp(19px, 1.7vw, 25px); margin-bottom: 9px; }
.mag p { font-size: 14.5px; color: #c3baa9; max-width: 46ch; }
.mag__second { margin-top: 10px; }
.mag__note { color: #8e8677; font-size: 12.5px; }
.gusset { position: absolute; inset: 0; width: 100%; height: 100%; }
.gusset__note text { font-family: var(--sans); font-size: 7px; letter-spacing: 0.08em; text-transform: uppercase; }

/* --- 7 worn by ----------------------------------------------------------- */
.worn__body { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: clamp(18px, 2.4vw, 42px); }
.worn__rule { position: relative; border-right: 1px solid var(--rule); min-height: 560px; }
.worn__tick { position: absolute; right: 0; width: 12px; height: 1px; background: var(--ink-3); }
.worn__tick i {
  position: absolute; right: 18px; top: -9px; font-style: normal;
  font-size: 11px; color: var(--ink-3); font-variant-numeric: var(--num); white-space: nowrap;
}
.worn__list { list-style: none; margin: 0; padding: 0; position: relative; min-height: 560px; }
.review {
  position: absolute; left: 0; right: 0; bottom: calc(var(--h) * 1% - 44px);
  max-width: 60ch; padding-left: 18px; border-left: 2px solid var(--dye);
}
.review__fit {
  font-size: 11.5px; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--ink-3); margin-bottom: 9px;
  font-variant-numeric: var(--num);
}
.review__h {
  display: inline-block; margin-right: 10px; padding: 2px 7px;
  background: var(--dye); color: var(--paper); font-weight: 600; letter-spacing: 0.03em;
}
.review blockquote {
  margin: 0 0 8px; font-family: var(--voice); font-size: clamp(17px, 1.55vw, 22px);
  line-height: 1.42; letter-spacing: -0.008em;
}
.review__name { font-size: 13px; color: var(--ink-2); }

/* --- 8 decide ------------------------------------------------------------ */
.buy { position: relative; overflow: hidden; color: #fbf6ec; padding-top: clamp(70px, 9vw, 140px); padding-bottom: clamp(70px, 9vw, 140px); }
.buy__cloth { position: absolute; inset: 0; }
.buy__cloth::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(105deg, rgba(16, 14, 12, 0.82), rgba(16, 14, 12, 0.42));
}
.buy__inner { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(300px, 0.85fr); gap: clamp(24px, 3.4vw, 64px); align-items: start; }
.sec--onCloth { grid-column: 1; }
.sec--onCloth h2 { color: #fbf6ec; }
.sec--onCloth .eyebrow { color: #d9cfbd; }
.buy__form { grid-column: 2; grid-row: 1 / span 2; background: rgba(250, 245, 236, 0.96); color: var(--ink); padding: clamp(20px, 2vw, 30px); }
.picked { list-style: none; margin: 0 0 22px; padding: 0; }
.picked li {
  display: grid; grid-template-columns: 62px 1fr auto; align-items: baseline; gap: 10px;
  padding: 11px 0; border-bottom: 1px solid var(--rule);
}
.picked__k { font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-3); }
.picked__v { font-size: 14.5px; color: var(--ink-3); font-variant-numeric: var(--num); }
.picked li.is-done .picked__v { color: var(--ink); font-weight: 500; }
.picked li a { font-size: 12px; color: var(--dye); }
.picked li a:hover { color: var(--ink); }
.add {
  width: 100%; padding: 15px 20px; border: 0;
  background: var(--ink); color: var(--paper);
  font-family: var(--disp); font-weight: 700; font-size: 17px; letter-spacing: -0.01em;
  font-variant-numeric: var(--num);
}
.add:not(:disabled):hover { background: var(--dye); }
.add:not(:disabled):active { transform: translateY(1px); }
.add:disabled { background: var(--paper-3); color: var(--ink-3); }
.add__why { margin-top: 10px; font-size: 12.5px; color: var(--ink-3); }
.bag {
  grid-column: 1; align-self: end;
  font-family: var(--voice); font-size: clamp(19px, 2vw, 30px); line-height: 1.35;
  max-width: 26ch; min-height: 1px;
}

/* --- returns -------------------------------------------------------------- */
.returns { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(260px, 0.8fr); gap: clamp(26px, 4vw, 72px); align-items: start; }
.returns__body { font-family: var(--voice); font-size: clamp(20px, 2.3vw, 32px); line-height: 1.36; letter-spacing: -0.012em; }
.returns__facts { list-style: none; margin: 0; padding: 0; }
.returns__facts li {
  display: flex; align-items: center; gap: 11px;
  padding: 13px 0; border-bottom: 1px solid var(--rule);
  font-size: 14.5px; color: var(--ink-2);
}
.returns__facts svg { color: var(--dye); flex: none; }
.returns__facts b { color: var(--ink); }

/* --- footer --------------------------------------------------------------- */
.foot {
  border-top: 1px solid var(--rule);
  padding: 36px var(--gut) 52px;
  display: grid; grid-template-columns: auto minmax(0, 62ch); gap: clamp(20px, 4vw, 70px);
  align-items: start;
}
.foot__mark { font-family: var(--disp); font-weight: 800; font-size: 22px; letter-spacing: -0.02em; }
.foot p { font-size: 12px; color: var(--ink-3); line-height: 1.6; }
.foot a { color: var(--ink-2); }
.foot a:hover { color: var(--ink); }

/* --- 900px ---------------------------------------------------------------- */
@media (max-width: 1080px) {
  .measure__body { grid-template-columns: 1fr; }
  .fit { position: static; }
  .worn__list, .worn__rule { min-height: 640px; }
}

@media (max-width: 900px) {
  .peak { height: 280vh; }
  .peak__sticky { grid-template-columns: 1fr; grid-template-rows: minmax(0, 1fr) auto; padding-top: 56px; gap: 20px; }
  .peak__frame { height: auto; min-height: 0; }
  .peak__cloth { position: relative; inset: auto; height: 32vh; }
  .peak__lamp { inset: -18% -6%; }
  .buy__inner { grid-template-columns: 1fr; }
  .buy__form { grid-column: 1; grid-row: auto; }
  .bag { grid-column: 1; }
  .returns { grid-template-columns: 1fr; }
  .mag--near, .mag--mid { grid-column: span 12; }
  .mag--gusset { grid-template-columns: 1fr; }
}

/* --- 390px: its own composition ------------------------------------------- */
@media (max-width: 700px) {
  body { font-size: 15px; }

  .bar { grid-template-columns: auto 1fr; padding: 9px 16px; gap: 10px; }
  .bar__product { display: none; }
  .bar__state {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 60;
    justify-content: space-between;
    padding: 10px 16px calc(10px + env(safe-area-inset-bottom));
    background: color-mix(in srgb, var(--paper) 94%, transparent);
    backdrop-filter: blur(12px);
    border-top: 1px solid var(--rule);
  }
  .bar__parts { font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .foot { padding-bottom: 96px; }

  /* The masthead is a band of cloth over the type, not two columns stacked. */
  .mast {
    grid-template-columns: 1fr;
    grid-template-areas: 'cloth' 'text' 'rule';
    min-height: 0; padding-top: 18px; gap: 0;
  }
  .mast__cloth { margin: 0 calc(var(--gut) * -1) 34px; }
  .mast__cloth .cv, .mast__cloth .cv--fallback { height: 40vh; box-shadow: none; }
  .mast__cap { left: var(--gut); bottom: -26px; }
  .mast h1 { font-size: clamp(40px, 13vw, 60px); }
  .deck { font-size: 15px; }
  .mast__rule { margin-top: 40px; }
  .jump { gap: 6px; }
  .jump a { font-size: 12px; padding: 6px 10px; }

  section { padding: 56px var(--gut); }

  /* The test keeps its mechanism; the slider becomes the primary driver. */
  .peak { height: 240vh; }
  .peak__sticky { padding: 52px var(--gut) 22px; }
  .peak__cloth { height: 30vh; }
  .peak h2 { font-size: 34px; margin-bottom: 14px; }
  .peak__stage { min-height: 4.2em; font-size: 14px; margin-bottom: 14px; }
  .readout { grid-template-columns: 1fr; margin-bottom: 16px; }
  .readout > div { padding: 7px 0; }
  .readout dd { font-size: 17px; }
  .scrub input[type='range'] { height: 34px; }
  .scrub input[type='range']::-webkit-slider-thumb { width: 24px; height: 24px; margin-top: -11px; }
  .peak__claim { font-size: 12.5px; }

  /* Six swatches read as a comparison only if they are all on screen. */
  .swatches { grid-template-columns: repeat(2, 1fr); gap: 10px 8px; }
  .swatch__cloth { aspect-ratio: 3 / 3.2; }
  .swatch__meta { padding-top: 9px; }

  /* The chart keeps true relative lengths; the numbers move under the bars. */
  .chart__scale { padding-left: 0; padding-right: 0; }
  .row { grid-template-columns: 46px minmax(0, 1fr); padding: 13px 0; row-gap: 6px; }
  .row__bars { grid-column: 2; }
  .bar { height: 13px; }
  .bar i { left: auto; right: 0; transform: translateX(calc(100% + 6px)); font-size: 10px; }
  .row__inseam { grid-column: 2; text-align: left; font-size: 11.5px; padding-top: 2px; }
  .row.is-rec::after { left: -10px; width: 6px; height: 6px; margin-top: -3px; }
  .row__flag { position: static; display: block; grid-column: 1 / -1; }

  .len { grid-template-columns: repeat(3, 1fr); gap: 8px; }
  .len__opt { padding: 12px 10px; gap: 12px; }
  .len__draw { height: 120px; }
  .len__meta b { font-size: 13.5px; }
  .len__cm { font-size: 11.5px; }
  .len__offered { font-size: 10px; }

  /* Reviews stop being positioned on the rule and become a read, with the
     height kept as the thing you scan for. */
  .worn__body { grid-template-columns: 1fr; gap: 0; }
  .worn__rule { display: none; }
  .worn__list { min-height: 0; display: grid; gap: 30px; }
  .review { position: static; max-width: none; }
  .review blockquote { font-size: 18px; }

  .buy__form { padding: 18px 16px; }
  .picked li { grid-template-columns: 54px 1fr auto; }
  .bag { font-size: 20px; max-width: none; margin-top: 22px; }
  .returns__body { font-size: 20px; }
  .foot { grid-template-columns: 1fr; gap: 18px; }
}

@media (max-width: 380px) {
  .len { grid-template-columns: 1fr; }
  .len__opt { grid-template-columns: 64px 1fr; grid-template-rows: auto; align-items: center; gap: 14px; }
  .len__draw { height: 84px; }
}

/* --- reduced motion -------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
  [data-enter] { transition: none; }
  [data-enter='out'] { opacity: 1; transform: none; }
  .bar, .peak__lamp, .swatch__cloth, .len__opt, .add, .fit__use, .jump a { transition: color 90ms linear, background-color 90ms linear, border-color 90ms linear; }
  .peak { height: auto; }
  .peak__sticky { position: static; height: auto; min-height: 0; }
  .peak__frame { height: 56vh; }
}

